function initMap(){try{
map=new maplibregl.Map({container:'map',style:'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json',center:[state.lon,state.lat],zoom:cities[state.city].zoom,pitch:45,bearing:-18,antialias:true,attributionControl:{compact:true},maxPitch:65});
map.addControl(new maplibregl.ScaleControl({maxWidth:100,unit:'metric'}),'bottom-left');
map.on('load',()=>{state.mapReady=true;$('#map-loading').hidden=true;addMapLayers();
networkRenderer=new TransportNetwork(map,{onStation:e=>showDetail(asStation(e)),onRoute:showRoute});if(state.network)networkRenderer.setData(state.network);
simulation=new CitySimulation(map,{onStats:stats=>{const n=typeof stats==='number'?stats:stats?.total??stats?.actors;$('#sim-count').textContent=n!==undefined?`${n} illustrative actors`:'illustrative movement';}});if(state.network)simulation.setNetwork(state.network);simulation.setActivities(state.data?.events||[]);
overlays=new EnvironmentalOverlays(map,{onAircraft:e=>showDetail({...e,category:'airspace',status:'published'}),onStatus:status=>{state.overlayStatus[status.id]=status;renderOverlayStatus();}});overlays.setArea({lat:state.lat,lon:state.lon,radius:state.radius});applyVisibility();renderMap();locationView.attach(map);world.attach(map);world.initMap();mission.attachMap(map,true);if(pendingCamera){const p=pendingCamera;pendingCamera=null;flyToPlace(p.e,p.zoom,p.pitch,p.keepFollow);}});
map.on('error',e=>{if(!state.mapReady){$('#map-loading').hidden=true;$('#map-message').textContent='Map tiles are unavailable. The area feed and location search remain available.';$('#map-message').hidden=false;}});
map.on('click','records',e=>{const id=e.features?.[0]?.properties.id;const event=allRecords().find(x=>x.id===id);if(event)showDetail(event);});
map.on('mouseenter','records',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','records',()=>map.getCanvas().style.cursor='');
map.on('dragstart',()=>{stopTour();mission?.stopTracking();mission?.stopScene();locationTracker?.suspend();});map.on('zoomstart',e=>{if(e.originalEvent){stopTour();mission?.stopTracking();mission?.stopScene();locationTracker?.suspend();}});
map.on('moveend',()=>{const c=map.getCenter();$('#scan-center').classList.toggle('changed',distance(c.lat,c.lng,state.lat,state.lon)>.25);});
}catch(e){$('#map-loading').hidden=true;$('#map-message').hidden=false;$('#map-message').textContent='Your browser could not start the map renderer. Explore the public records in the area feed.';}}
function circleGeo(lon,lat,radius){return {type:'Feature',properties:{},geometry:{type:'Polygon',coordinates:[Array.from({length:97},(_,i)=>{const a=i/96*Math.PI*2;return [lon+radius*Math.cos(a)/(111.32*Math.cos(lat*Math.PI/180)),lat+radius*Math.sin(a)/110.574];})]}};}
