async function loadData(manual=false){
abort?.abort();abort=new AbortController();const request=++state.request;state.loading=true;render();
try{const p=new URLSearchParams({lat:String(state.lat),lon:String(state.lon),radius:String(state.radius),city:state.city});const r=await fetch('/api/overview?'+p,{signal:abort.signal});const d=await r.json();if(!r.ok)throw new Error(d.error||'Data is unavailable.');if(request!==state.request)return;state.data=d;simulation?.setActivities(d.events||[]);updateTools();$('#last-sync').textContent='SYNC '+new Date().toISOString().slice(11,19)+' UTC';if(manual)toast('Area feeds refreshed. Individual sources may have different publication times.');}
catch(e){if(e.name==='AbortError')return;if(request!==state.request)return;toast(state.data?'Refresh failed. Previously fetched records remain visible; check their timestamps.':e.message);if(!state.data){$('#activity-list').innerHTML=`<div class="empty-state">${svg('info',26)}<strong>Public feeds could not be reached</strong><p>Try refreshing. You can still explore the map and search for an area.</p></div>`;}}
finally{if(request===state.request){state.loading=false;render();}}
}
