 await Promise.allSettled(['transport','explore'].map(async kind=>{try{const r=await fetch('/api/'+kind+'?'+params,{signal:contextAbort.signal});if(!r.ok)throw new Error(kind+' data is unavailable');const d=await r.json();if(n!==contextRequest)return;if(kind==='transport'){state.network=d;networkRenderer?.setData(d);simNetworkData=null;}else state.explore=d;updateTools();render();}catch(e){if(e.name!=='AbortError'&&n===contextRequest)toast(e.message);}}));
