function initIntelligence(){intelligence=new IntelligenceTools({onReplay:snapshot=>{if(!snapshot&&!state.replay)return;stopTour();locationTracker?.suspend();locationView?.clearFocus();state.locationFocus=null;closeDetail();state.replay=snapshot;if(snapshot){if(snapshot.center){state.lat=snapshot.center.lat;state.lon=snapshot.center.lon;}if(cities[snapshot.city]){state.city=snapshot.city;$('#city').value=state.city;}if(snapshot.radius){state.radius=snapshot.radius;document.querySelectorAll('[data-radius]').forEach(b=>b.classList.toggle('active',Number(b.dataset.radius)===state.radius));}highlightConnections({});loadContext();flyToPlace({lat:state.lat,lon:state.lon},cities[state.city].zoom,45);}else{loadData();loadContext();}render();},onHighlights:highlightConnections,onFilter:applySignalCommand,onFly:e=>flyToPlace(e),onError:toast});intelligence.mount($('#intelligence-content'));updateTools();}
function applySignalCommand(filter){state.signal=filter.signal||null;state.signalLayer=filter.layerPreset||null;state.query=filter.query||filter.line||'';$('#record-query').value=state.query;state.listLimit=60;
 const preset=filter.layerPreset;if(preset==='transit'){state.enabled.add('transit');MODES.forEach(m=>state.enabled.add(m));state.enabled.add('stations');}else if(preset==='activity')state.enabled.add('traffic');else if(preset==='nature'){STORY_CATEGORIES.forEach(k=>state.enabled.delete(k));['parks','geography'].forEach(k=>state.enabled.add(k));}else if(preset==='stories')STORY_CATEGORIES.forEach(k=>state.enabled.add(k));if(filter.line){MODES.forEach(k=>state.enabled.add(k));state.enabled.add('stations');highlightConnections({lineNames:[filter.line]});}if(filter.tab&&['all','activity','stations','stories'].includes(filter.tab))setTab(filter.tab);else setTab('all');persist();render();}
function setTab(tab){state.tab=tab;state.listLimit=60;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));}
function showDetail(e,fromTour=false){
 if(mission?.drawMode)return;
 if(!fromTour)stopTour();state.selected=e.id;detailAbort?.abort();const request=++detailRequest,l=layers[e.category]||layers.places,isRef=e.status==='reference',canStory=isRef&&!e.worldKind&&!e.isRoute,url=safeUrl(e.sourceUrl);document.body.classList.remove('show-feed','show-layers');$('#world-drawer').hidden=true;$('#mission-drawer').hidden=true;
 $('#detail-container').innerHTML=`<section class="detail-panel" role="dialog" aria-labelledby="detail-title" style="--layer:${l.color}"><button id="close-detail" class="icon-button detail-close" aria-label="Close record details">${svg('close')}</button><div class="detail-eyebrow">${svg(l.icon,16)} ${esc(l.name.toUpperCase())}</div><h2 id="detail-title">${esc(e.title)}</h2><div class="detail-chips"><span>${fmtDistance(e.distance??distance(state.lat,state.lon,e.lat,e.lon))} from centre</span><span>${e.isRoute?'PUBLISHED ROUTE':isRef?'REFERENCE / HISTORY':'PUBLIC RECORD'}</span></div>${e.lines?.length?`<div class="line-badges">${e.lines.map(line=>`<button data-line="${esc(line)}">${esc(line)}</button>`).join('')}</div>`:''}<p class="detail-description">${esc(e.description||'No description supplied.')}</p>${e.audioUrl&&safeUrl(e.audioUrl).startsWith('https:')?`<audio controls preload="none" src="${esc(safeUrl(e.audioUrl))}" aria-label="Play ${esc(e.title)} radio stream"></audio><p class="detail-note">Live broadcaster stream; availability and terms depend on the station.</p>`:''}${e.imageUrl&&safeUrl(e.imageUrl).startsWith('https:')?`<figure class="story-image"><img src="${esc(safeUrl(e.imageUrl))}" alt="${esc(e.title)}" loading="lazy"><figcaption>${esc(e.license||'Image license and contributor: see original source.')}</figcaption></figure>`:''}${e.tle1?'<button id="satellite-passes" class="detail-map-link">Calculate passes over scan centre</button><div id="satellite-pass-list"></div>':''}<div id="place-story">${canStory?'<div class="story-loading"><span class="spinner"></span> Reading this place’s history…</div>':''}</div><dl><div><dt>Source</dt><dd>${esc(e.source)}</dd></div>${e.updatedAt||e.publishedAt?`<div><dt>Source time</dt><dd>${esc(formatTime(e.updatedAt||e.publishedAt))}</dd></div>`:''}${e.startsAt?`<div><dt>Starts / departure</dt><dd>${esc(formatTime(e.startsAt))}</dd></div>`:''}${e.expiresAt?`<div><dt>Ends / expires</dt><dd>${esc(formatTime(e.expiresAt))}</dd></div>`:''}<div><dt>Coordinates</dt><dd>${Number(e.lat).toFixed(5)}, ${Number(e.lon).toFixed(5)}</dd></div>${Number.isFinite(e.altitude)?`<div><dt>Altitude</dt><dd>${esc(e.altitude)} m</dd></div>`:''}${Number.isFinite(e.speed)?`<div><dt>Speed</dt><dd>${esc(e.speed)} km/h</dd></div>`:''}</dl><p class="detail-note">${e.isRoute?'Route geometry comes from a published timetable snapshot; pattern and service availability can change.':isRef?'Historical and geographic context. This marker does not imply current activity.':'Published information may be incomplete or approximate. Activity scenes are illustrative simulations.'}</p>${url!=='#'?`<a class="primary-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open original source ${svg('link',15)}</a>`:''}<div class="detail-actions"><button id="detail-map">${svg('compass',14)} Fly closer</button><button id="street-teleport">${svg('eye',14)} Street view</button></div><div id="street-links" hidden><p>Street-level map perspective. Public panorama availability is checked by the imagery provider.</p><a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${encodeURIComponent(e.lat+','+e.lon)}">Open available Street View ${svg('link',12)}</a></div><button class="detail-map-link" id="explore-here">Explore around this place ${svg('target',14)}</button></section>`;
 $('#close-detail').onclick=closeDetail;$('#detail-map').onclick=()=>flyToPlace(e,17.4,62);$('#street-teleport').onclick=()=>{flyToPlace(e,18.4,65);$('#street-links').hidden=false;};$('#explore-here').onclick=()=>scan(e.lat,e.lon);document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>{state.query=b.dataset.line;state.signal=null;state.signalLayer=null;$('#record-query').value=state.query;state.enabled.add('stations');MODES.forEach(m=>state.enabled.add(m));setTab('stations');highlightConnections({lineNames:[b.dataset.line]});render();});$('#close-detail').focus({preventScroll:true});flyToPlace(e,e.isRoute?14.6:15.8);
 if(e.tle1)$('#satellite-passes').onclick=()=>{try{const passes=satellitePasses(e,{lat:state.lat,lon:state.lon});$('#satellite-pass-list').innerHTML='<p class="detail-note">Next 24 hours above 10° elevation. One-minute geometric predictions from these orbital elements; daylight, clouds and visibility are not evaluated.</p>'+passes.map(p=>`<p class="detail-note">${esc(formatTime(p.rise))} → ${p.set?esc(formatTime(p.set)):'after window'} · peak ${p.maxElevation.toFixed(0)}°</p>`).join('')+(passes.length?'':'<p class="detail-note">No pass above 10° predicted in this window.</p>');}catch(err){toast(err.message);}};
 if(canStory)loadPlaceStory(e,request);
}
async function loadPlaceStory(e,request){
 detailAbort=new AbortController();try{const params=new URLSearchParams({id:e.id,title:e.wikiTitle||e.title,lat:e.lat,lon:e.lon});if(e.pageId)params.set('pageId',e.pageId);const r=await fetch('/api/place?'+params,{signal:detailAbort.signal});const d=await r.json();if(request!==detailRequest||!$('#place-story'))return;if(!r.ok)throw new Error(d.error||'Historical source unavailable');const extract=d.extract||d.description;if(!extract){$('#place-story').innerHTML='<p class="story-unavailable">No verified history text was found for this place. Use the original source link below.</p>';return;}const image=d.image&&safeUrl(d.image.url)!=='#'?`<figure class="story-image"><img src="${esc(safeUrl(d.image.url))}" alt="${esc(d.title||e.title)}" loading="lazy"><figcaption>${esc(d.image.attribution||'Wikimedia Commons')} · ${esc(d.image.license||'See original image license')} ${d.image.sourceUrl?`<a href="${esc(safeUrl(d.image.sourceUrl))}" target="_blank" rel="noopener noreferrer">Image source</a>`:''}</figcaption></figure>`:'';$('#place-story').innerHTML=`${image}<div class="story-header">${svg('clock',14)} HISTORY & PLACE NOTES</div>${d.note?`<p class="story-match-note">${esc(d.note)}</p>`:''}<div class="story-extract">${String(extract).split(/\n\s*\n/).map(t=>`<p>${esc(t)}</p>`).join('')}</div><div class="story-attribution">Excerpt from <a href="${esc(safeUrl(d.sourceUrl||e.sourceUrl))}" target="_blank" rel="noopener noreferrer">${esc(d.title||e.title)} · ${esc(d.source||'Wikipedia')}</a>. ${esc(typeof d.attribution==='string'?d.attribution:d.license||'CC BY-SA 4.0')}. Text may be shortened for display.</div>`;}catch(error){if(error.name==='AbortError'||request!==detailRequest)return;if($('#place-story'))$('#place-story').innerHTML=`<p class="story-unavailable">${esc(error.message)}. The original source remains available below.</p>`;}}
function closeDetail(){detailRequest++;detailAbort?.abort();const id=state.selected;state.selected=null;$('#detail-container').innerHTML='';Array.from(document.querySelectorAll('[data-record]')).find(el=>el.dataset.record===id)?.focus({preventScroll:true});}
function showModal(kind){const sources=mergedSources();$('#modal-container').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" aria-label="Close dialog">${svg('close')}</button><div class="eyebrow">${kind==='sources'?'PROVENANCE / FEED HEALTH':'THE OBSERVATORY'}</div><h2 id="modal-title">${kind==='sources'?'A view with receipts.':'More context. Less guessing.'}</h2><p class="modal-intro">${kind==='sources'?'Every layer has a source. Connected means the latest request succeeded; it does not guarantee complete or instant coverage.':'Around Me brings public activity and place information into one map. Explore what is published around you, with the original source always in reach.'}</p>${kind==='sources'?sources.length?sources.map(s=>`<article class="source-row"><div><i class="source-dot ${s.status==='connected'?'connected':''}"></i><h3>${esc(s.name)}</h3><span>${esc(s.status)}</span></div><p>${esc(s.note||'')}</p><div class="source-meta"><span>${esc(s.license||'See provider terms')}</span><span>${Number(s.count)||0} records</span></div><div class="source-meta"><span>${s.updatedAt?'Source / checked '+esc(formatTime(s.updatedAt)):'Not fetched'}</span><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">Provider ${svg('link',11)}</a></div></article>`).join(''):'<div class="empty-state"><p>Sources will appear when the first area request completes.</p></div>':`<div class="about-grid"><div>${svg('clock',22)}<h3>Different signals, different clocks.</h3><p>Weather, planned works, published reports and places refresh on different schedules. Check source times before drawing conclusions.</p></div><div>${svg('target',22)}<h3>Your area is the starting point.</h3><p>Search, use your location, or move the map and scan its centre. The ring shows the selected radius.</p></div><div>${svg('eye',22)}<h3>Gaps stay visible.</h3><p>An empty feed means no matching records were returned. It cannot establish that an area is quiet or explain an unreported incident.</p></div><div>${svg('layers',22)}<h3>Activity and context.</h3><p>Landmarks and transit stops describe an area. They are reference locations, not live incidents. Moving people, cars, crews and transit vehicles are simulations along mapped paths. Their positions are not observations. The 4× motion speed is illustrative. Network geometry and historical excerpts have their own provenance.</p></div></div><p class="about-privacy">Location is requested only when you choose “My location”. Coordinates are sent to the public data providers needed for your scan. Replay observations, including their observation area, are stored only in this browser for up to 48 hours. Use Replay’s clear control to remove them. City and layer preferences also stay in this browser.</p><p class="about-privacy">Map: © OpenStreetMap contributors, © CARTO. Satellite imagery: © Esri, Vantor, Earthstar Geographics, GIS User Community; imagery dates vary. Weather and air quality: Open-Meteo (CC BY 4.0; free service for noncommercial use). Place search: Photon / OpenStreetMap. Individual feed terms appear in Source network.</p>`}</section></div>`;$('.modal-close').onclick=closeModal;$('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal();};$('.modal-close').focus();}
function closeModal(){$('#modal-container').innerHTML='';$('#sources-button').focus();}
function toggleOrbit(){state.orbit=!state.orbit;$('#orbit').classList.toggle('active',state.orbit);$('#orbit').setAttribute('aria-pressed',String(state.orbit));if(orbitFrame)cancelAnimationFrame(orbitFrame);const step=t=>{if(!state.orbit||!map)return;if(lastFrame&&t-lastFrame<200&&state.mapReady)map.setBearing(map.getBearing()+(t-lastFrame)*.0015);lastFrame=t;orbitFrame=requestAnimationFrame(step);};if(state.orbit){if(matchMedia('(prefers-reduced-motion: reduce)').matches){state.orbit=false;$('#orbit').classList.remove('active');$('#orbit').setAttribute('aria-pressed','false');toast('Orbit stays off while reduced motion is enabled.');return;}lastFrame=0;orbitFrame=requestAnimationFrame(step);}}
function initExtras(){
 $('#layer-query').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.layer-group').forEach(group=>{let n=0;group.querySelectorAll('[data-layer]').forEach(b=>{const l=layers[b.dataset.layer],visible=!q||(l.name+' '+l.hint+' '+l.group).toLowerCase().includes(q);b.hidden=!visible;if(visible)n++;});group.hidden=!n;if(q&&n)group.open=true;});};
 document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{stopTour();if(b.dataset.preset==='all')state.enabled=new Set(defaultLayers);else if(b.dataset.preset==='transport')state.enabled=new Set([...MODES,'stations','labels','baseLabels','buildings','scanRing','motion','buses','trains','trams','transit','environment']);else state.enabled=new Set([...STORY_CATEGORIES,'labels','baseLabels','buildings','scanRing','environment','motion','people','cars']);state.query='';state.signal=null;state.signalLayer=null;$('#record-query').value='';setTab(b.dataset.preset==='stories'?'stories':b.dataset.preset==='transport'?'stations':'all');persist();render();});
 $('#sim-pause').onclick=()=>{state.simOverride=true;state.simPaused=!state.simPaused;$('#sim-pause').setAttribute('aria-label',state.simPaused?'Resume simulated movement':'Pause simulated movement');render();};
 $('#focus-button').onclick=()=>{state.focus=!state.focus;document.body.classList.toggle('focus-map',state.focus);$('#focus-button').innerHTML=svg('target',14)+(state.focus?' Show panels':' Full map');setTimeout(()=>map?.resize(),280);};
 $('#tools-button').onclick=()=>{state.toolsOpen=!state.toolsOpen;$('#intelligence-drawer').hidden=!state.toolsOpen;$('#tools-button').classList.toggle('active',state.toolsOpen);};$('#close-tools').onclick=()=>{state.toolsOpen=false;$('#intelligence-drawer').hidden=true;$('#tools-button').classList.remove('active');$('#tools-button').focus();};
 $('#tour-button').onclick=()=>{if(state.tour){stopTour();return;}const places=allRecords().filter(e=>STORY_CATEGORIES.includes(e.category)).sort((a,b)=>a.distance-b.distance);const stops=[];for(const e of places){if(stops.every(p=>distance(p.lat,p.lon,e.lat,e.lon)>.45))stops.push(e);if(stops.length===8)break;}if(!stops.length){toast('Load a Berlin area with story layers to start the flying tour.');return;}state.tour=true;$('#tour-button').classList.add('active');$('#tour-button').innerHTML=svg('pause',14)+' Stop tour';let index=0;const step=()=>{if(!state.tour)return;showDetail(stops[index++%stops.length],true);tourTimer=setTimeout(step,13000);};step();};
}
