$('#city').onchange=e=>{state.city=e.target.value;searchRequest++;searchAbort?.abort();$('#search-results').hidden=true;state.query='';$('#record-query').value='';const c=cities[state.city];persist();$('#location-query').value='';scan(c.lat,c.lon,false);flyToPlace(c,c.zoom,45);};
