$('#refresh').onclick=()=>{if(state.replay){intelligence?.live();return;}loadData(true);};$('#sources-button').onclick=()=>showModal('sources');$('#footer-sources').onclick=()=>showModal('sources');$('#info-button').onclick=()=>showModal('about');
