$('#zoom-in').onclick=()=>map?.zoomIn();$('#zoom-out').onclick=()=>map?.zoomOut();$('#north').onclick=()=>map?.easeTo({bearing:0});$('#home').onclick=()=>flyToPlace({lon:state.lon,lat:state.lat},state.locationFocus?17.2:cities[state.city].zoom,50);$('#orbit').onclick=()=>{stopTour();toggleOrbit();};
$('#three-d').onclick=()=>{state.threeD=!state.threeD;$('#three-d').classList.toggle('active',state.threeD);$('#three-d').setAttribute('aria-pressed',String(state.threeD));if(state.threeD)state.enabled.add('buildings');map?.easeTo({pitch:state.threeD?55:0});if(map?.getLayer('city-buildings-3d'))map.setLayoutProperty('city-buildings-3d','visibility',state.threeD&&state.enabled.has('buildings')?'visible':'none');render();};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));if(!state.mapReady)return;const satellite=state.view==='satellite';map.setLayoutProperty('satellite-imagery','visibility',satellite?'visible':'none');baseLayers.forEach(l=>{if(map.getLayer(l.id))map.setLayoutProperty(l.id,'visibility',satellite&&l.type!=='symbol'?'none':l.visibility);if(l.type==='background')map.setPaintProperty(l.id,'background-color',state.view==='street'?'#1c242c':'#080e16');if(l.id==='water')map.setPaintProperty(l.id,'fill-color',state.view==='street'?'#1c4354':'#102732');});applyVisibility();toast(satellite?'Satellite imagery is a geographic backdrop, not a live video feed.':state.view==='street'?'Street view: brighter geographic context.':'Tactical view: dark geographic context.');});
$('#locate').onclick=()=>{stopTour();searchRequest++;searchAbort?.abort();$('#search-results').hidden=true;locationTracker.locate();};
$('#search-form').onsubmit=async e=>{
 e.preventDefault();const q=$('#location-query').value.trim();
 if(/^(my (current )?location|current location|where am i|near me|mein standort|meine position)$/i.test(q)){$('#locate').onclick();return;}
 const coordinate=coordinateSearch(q);if(coordinate){selectSearch(coordinate);return;}
 if(q.length<3){toast('Enter at least three characters to search.');return;}
 locationTracker.suspend();const request=++searchRequest;searchAbort?.abort();searchAbort=new AbortController();$('#search-results').hidden=false;$('#search-results').textContent='Searching places…';
 try{const r=await fetch('/api/search?'+new URLSearchParams({q,lat:state.lat,lon:state.lon}),{signal:searchAbort.signal});const d=await r.json();if(request!==searchRequest)return;if(!r.ok)throw new Error(d.error);const results=(d.results||[]).filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lon)&&Math.abs(x.lat)<=85&&Math.abs(x.lon)<=180&&typeof x.label==='string');if(!results.length){$('#search-results').textContent='No places found. Try a street name or scan the map.';return;}
 selectSearch(results[0]);$('#search-results').innerHTML='<p>Flying to the first match. Choose another:</p>'+results.map((x,i)=>`<button data-search="${i}" aria-label="Fly to ${esc(x.label)}">${svg('places',14)}<span>${esc(x.label)}</span></button>`).join('');$('#search-results').hidden=results.length<2;document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>selectSearch(results[Number(b.dataset.search)]));
 }catch(e){if(e.name==='AbortError'||request!==searchRequest)return;$('#search-results').textContent=e.message||'Place search unavailable. Try the map.';}
};
$('#pause').onclick=()=>{state.paused=!state.paused;$('#pause').innerHTML=svg(state.paused?'play':'pause',12)+(state.paused?' RESUME REFRESH':' AUTO REFRESH');render();if(!state.paused&&!state.replay)loadData();};
$('#export').onclick=()=>{const records=visibleRecords();if(!records.length){toast('There are no visible records to export.');return;}const data={type:'FeatureCollection',metadata:{exportedAt:new Date().toISOString(),city:state.city,radiusKm:state.radius,description:'Public source records and reference places. Source times and terms vary.'},features:records.map(e=>({type:'Feature',geometry:{type:'Point',coordinates:[e.lon,e.lat]},properties:e}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/geo+json'}));const a=document.createElement('a');a.href=url;a.download=`around-me-${state.city}-${new Date().toISOString().slice(0,10)}.geojson`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Visible records exported with source details.');};
