document.addEventListener('keydown',e=>{if(e.key==='Escape'){stopTour();$('#world-drawer').hidden=true;$('#mission-drawer').hidden=true;if(state.toolsOpen){state.toolsOpen=false;$('#intelligence-drawer').hidden=true;}if($('#modal-container').children.length)closeModal();else closeDetail();$('#search-results').hidden=true;document.body.classList.remove('show-layers','show-feed');}if(e.key==='Tab'&&$('#modal-container').children.length){const els=$('#modal-container').querySelectorAll('button,a[href]'),first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
